export const IGES_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/iges-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getIgesStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(IGES_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
